const SITE = {"phone":"4122123136","quote":"People are strange, when you're a stranger. Faces look ugly, when you're alone.","newsletter":"https://script.google.com/macros/s/AKfycbznqG0QukoKDsuQ9OLtxWTzbXwXgpIO-e8XtuUMY1w-u5YVd121UPKIxl634QdVKtiDUA/exec","support":""};   // {phone, quote, newsletter, support}
const KINDS = ["Mass","Confession","Adoration"];
const CATS = [{"s":"festivals","n":"Festivals & outings","d":"Fairs, markets, food events, and things going on in the parks. A lot of these are free."},{"s":"talks","n":"Talks, tours & museums","d":"Lectures, walking tours, gallery openings, and museum events."},{"s":"music","n":"Live music","d":"Everything from karaoke and open stage nights to big concerts."},{"s":"catholic","n":"Catholic events","d":"Socials, talks, service projects, and Bible studies at parishes around Pittsburgh."},{"s":"comedy","n":"Comedy & theater","d":"Stand-up, improv, plays, and shows."}];
const catBySlug = Object.fromEntries(CATS.map(c => [c.s, c]));
const lower = c => c.s === "catholic" ? c.n : c.n.toLowerCase();
const catHref = c => `/events/${c.s}/`;
const PARISHES = [...new Set([...SCHED.map(p => p.p), ...EVENTS.filter(e => e.cat === "Catholic events").flatMap(e => e.src.map(s => s[0]))])].filter(Boolean).sort();
const TYPES = ["Volunteer","Social","Speaker","Study","Prayer and Worship","Retreat","Confession","Adoration","Group","Aid Distribution"];
const AUD = [["all","Everyone"],["young adults","Young adults"],["seniors","Seniors"],["men","Men"],["women","Women"],["families","Families"]];
// An event's own id always opens that event; an old id opens the event it became.
const byId = Object.fromEntries([...EVENTS.flatMap(e => (e.al || []).map(x => [x, e])), ...EVENTS.map(e => [e.id, e])]);
const main = document.getElementById("main");
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const pd = s => { const [y,m,d] = s.split("-").map(Number); return new Date(y, m-1, d); };
const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const longDay = s => pd(s).toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"});
const shortDay = s => pd(s).toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"});
const tm = t => t ? t.replace(/^0/,"").replace(/(AM|PM)$/," $1") : "";
const TODAY = iso(new Date());

// Text-message links. Until a number is set, they show [NUMBER] and go nowhere.
const PHONE_SHOWN = SITE.phone ? SITE.phone.replace(/^(\d{3})(\d{3})(\d{4})$/, "$1 $2 $3") : "[NUMBER]";
const sms = body => SITE.phone ? `sms:+1${SITE.phone}?&body=${encodeURIComponent(body)}` : "#";

function occurrences(list){
  const rows = [];
  for (const e of list){
    if (e.dates.length) { for (const d of e.dates) rows.push({d, e}); }
    else if (e.ds) rows.push({d: e.ds > TODAY ? e.ds : TODAY, e});
  }
  rows.sort((a,b) => a.d.localeCompare(b.d) || (a.e.st ? 0 : 1) - (b.e.st ? 0 : 1) ||
    toMin(a.e.st) - toMin(b.e.st) || a.e.t.localeCompare(b.e.t));
  return rows;
}
function toMin(t){ if(!t) return 9999; const m=t.match(/(\d+):(\d+)(AM|PM)/); let h=+m[1]%12; if(m[3]==="PM") h+=12; return h*60+ +m[2]; }

function home(){
  const offers = [
    ["Catch a movie", "You pick the movie.", "Hi Mick, want to catch a movie sometime?"],
    ["Take a walk", "Any park or trail you like.", "Hi Mick, want to take a walk sometime?"],
    ["Go to a museum or the library", "Phipps, Frick, Carnegie, etc.", "Hi Mick, want to go to a museum or the library sometime?"],
    ["Play a game", "I (sort of) know Backgammon and Chess. Or you can teach me a new one.", "Hi Mick, want to play a game sometime?"],
  ];
  main.innerHTML = `
    <section class="center">
      <p class="spaced">LONELY?</p>
      <h2 class="big">Let's grab a cup of coffee.</h2>
      <p class="narrow" style="margin-top:0;margin-bottom:12px"><i>${esc(SITE.quote)}</i> The Doors got it right with that one. I've been there plenty of times myself. But then one of those "ugly" faces smiles at me, and it shakes me out of it.</p>
      <p class="narrow" style="margin-top:0;margin-bottom:18px">If it's been awhile since an ugly face smiled at you, I volunteer mine :) Pick a coffee shop and let me join you. -Mick</p>
      <a class="btn" href="${sms("Hi Mick, I saw your site. Want to grab coffee sometime?")}">Let's get coffee</a>
      <p class="muted small" style="margin:12px 0 0">Or just text me at ${esc(PHONE_SHOWN)}.</p>
    </section>
    <hr class="big">
    <section>
      <p class="spaced">OR WE COULD</p>
      <div class="grid2">
        ${offers.map(([t,d,b]) => `<div><a class="big-link" href="${sms(b)}">${esc(t)}</a><div class="muted small">${esc(d)}</div></div>`).join("")}
      </div>
    </section>
    <hr class="big">
    <section>
      <p class="spaced" style="margin-bottom:4px">GOING ON THIS WEEK</p>
      <p style="margin:8px 0">These are some of the things I'm interested in, so I built a few web tools that collect events in each. If one of these looks good and you don't want to go alone, let's go together.</p>
      ${CATS.map(c => `<h3 class="cat">${esc(c.n)}</h3><p class="tight">${esc(c.d)}</p><p style="margin:0"><a href="${catHref(c)}">See ${esc(lower(c))}</a></p>`).join("")}
      <p style="margin:22px 0 0">If there's something you want to go to that isn't on here, tell me about it. I like checking out new things. Honestly, when someone shares what they're passionate about, it sometimes becomes infectious and you end up discovering that you like it too. So don't be shy!</p>
    </section>
    ${SITE.newsletter ? `
    <hr class="big">
    <section class="center">
      <p class="spaced" style="margin-bottom:10px">EVERY SUNDAY BY EMAIL</p>
      <p style="margin:0 0 12px">I pick a few of the most interesting events and send them to you, along with general LMJY updates.</p>
      <form class="signup" id="signup">
        <label for="em" class="vh">Email address</label>
        <input id="em" name="email" type="email" required placeholder="you@example.com">
        <label class="vh" aria-hidden="true">Leave this empty <input name="website" tabindex="-1" autocomplete="off"></label>
        <button type="submit">Sign up</button>
      </form>
      <p class="small" id="signupMsg" role="status" style="margin:10px 0 0"></p>
    </section>` : ""}
    <hr class="big">
    <section>
      <p class="spaced">HI, I'M MICK</p>
      <p style="margin:0 0 12px">I live in Pittsburgh, and I made this site to try and lower the amount of isolation in our community. The "ugly faces" thing is from <a href="https://www.youtube.com/watch?v=AgHaGrZkkv4" target="_blank" rel="noopener">People Are Strange</a> by The Doors. It basically means that isolation is a big problem because it makes other people seem ugly and frightening to us. But when an "ugly" face smiles at us, it challenges that lie. Because there's no such thing as an ugly face with a smile on it. If you want to support the site, please check out the links below.</p>
      <p class="center" style="margin:0"><a href="${SITE.phone ? sms("Hi Mick, I'd like to volunteer with LMJY.") : "/"}">Volunteer</a> &nbsp;|&nbsp; <a href="${SITE.support ? esc(SITE.support) : "/support/"}">Support this site</a></p>
    </section>`;
}

function readFilters(cat){
  const q = new URLSearchParams(location.search);
  return {cat, from:q.get("from")||TODAY, span:q.get("span")||"14", type:q.get("type")||"", aud:q.get("aud")||"",
          p:q.get("p")||"", zip:(q.get("zip")||"").trim(), mi:q.get("mi")||"10"};
}
function miles(a, b){
  const r = x => x*Math.PI/180, dLat = r(b[0]-a[0]), dLon = r(b[1]-a[1]);
  const h = Math.sin(dLat/2)**2 + Math.cos(r(a[0]))*Math.cos(r(b[0]))*Math.sin(dLon/2)**2;
  return 3958.8*2*Math.asin(Math.sqrt(h));
}
function catNav(cur){
  return `<nav class="cats">${CATS.map(c => `<span class="nw">${c.s === cur ? `<b>${esc(c.n)}</b>` : `<a href="${catHref(c)}">${esc(c.n)}</a>`}</span>`).join(" &nbsp;·&nbsp; ")}</nav><hr>`;
}
function list(slug){
  const f = readFilters(slug);
  const c = catBySlug[f.cat] || CATS[3];
  const catholic = c.s === "catholic";
  const end = new Date(pd(f.from)); end.setDate(end.getDate() + (f.span==="1"?0:f.span==="7"?6:f.span==="14"?13:3650));
  const endIso = iso(end);
  const home = f.zip ? ZIPS[f.zip] : null;
  const badZip = f.zip && !home;
  const dist = e => (home && e.ll) ? miles(home, e.ll) : null;
  const inCat = EVENTS.filter(e => e.cat === c.n);
  // A date span (a run of shows, an exhibit) shows on the first day of the view it overlaps.
  const rows = [];
  for (const e of inCat){
    if (catholic && ((f.type && e.ty !== f.type) || (f.aud && e.au !== f.aud) || (f.p && !e.src.some(s => s[0] === f.p)))) continue;
    if (home && !(e.ll && dist(e) <= +f.mi)) continue;
    if (e.dates.length){ for (const d of e.dates) if (d >= f.from && d <= endIso) rows.push({d, e}); }
    else if (e.ds && e.ds <= endIso && (e.de || e.ds) >= f.from) rows.push({d: e.ds > f.from ? e.ds : f.from, e});
  }
  rows.sort((a,b) => a.d.localeCompare(b.d) || (a.e.st ? 0 : 1) - (b.e.st ? 0 : 1) || toMin(a.e.st) - toMin(b.e.st) || a.e.t.localeCompare(b.e.t));
  const opt = (v,l,cur) => `<option value="${esc(v)}"${v===cur?" selected":""}>${esc(l)}</option>`;
  let html = catNav(c.s) + `
    <h2 class="big center" style="font-size:28px">${esc(c.n)}</h2>
    <form class="filters" id="ff">
      <label>Starting <input type="date" name="from" value="${f.from}" min="${TODAY}"></label>
      <label>Show <select name="span">${opt("1","that day",f.span)}${opt("7","7 days",f.span)}${opt("14","14 days",f.span)}${opt("all","everything after",f.span)}</select></label><br>
      ${catholic ? `<label>Kind <select name="type">${opt("","any kind",f.type)}${TYPES.map(t=>opt(t,t,f.type)).join("")}</select></label>
      <label>For <select name="aud">${opt("","anyone",f.aud)}${AUD.map(([v,l])=>opt(v,l,f.aud)).join("")}</select></label><br>
      <label>Parish <select name="p">${opt("","any parish",f.p)}${PARISHES.map(p=>opt(p,p,f.p)).join("")}</select></label><br>` : ""}
      <label>Near zip <input name="zip" size="5" maxlength="5" inputmode="numeric" value="${esc(f.zip)}" placeholder="15222"></label>
      <label>within <select name="mi">${["5","10","25","50"].map(m=>opt(m,m+" miles",f.mi)).join("")}</select></label>
      <button type="submit">Go</button>
      ${badZip?`<div class="note">I don’t have zip code ${esc(f.zip)}. Try a nearby zip in western Pennsylvania.</div>`:""}
    </form>
    ${catholic ? `<p class="note center">Regular weekly Mass, confession, and adoration times are on the <a href="/schedules/">Mass, confession &amp; adoration</a> page.</p>` : ""}
    <p class="count">${rows.length} event${rows.length===1?"":"s"}</p>
    ${f.span==="14" && rows.length ? `<p class="note center">Showing all events for the next 14 days. To see further out, use the search dropdown features above.</p>` : ""}`;
  let cur = "";
  for (const r of rows){
    if (r.d !== cur){ if (cur) html += "</ul>"; cur = r.d; html += `<h2 class="day">${esc(longDay(r.d))}</h2><ul class="ev">`; }
    const e = r.e;
    const when = e.st ? esc(tm(e.st)) : `<span class="where">${e.dn ? "Dates vary" : "No time listed"}</span>`;
    html += `<li><span class="tm">${when}</span><a href="/event/${e.id}/?d=${r.d}">${esc(e.t)}</a><br><span class="where">${esc(e.v)}${e.tw?", "+esc(e.tw):""}${home&&e.ll?`, ${dist(e).toFixed(1)} mi`:""}</span></li>`;
  }
  if (cur) html += "</ul>";
  if (!rows.length) html += `<p class="center">Nothing matches. Try “everything after” or a wider distance.</p>`;
  main.innerHTML = html;
  document.getElementById("ff").addEventListener("submit", ev => {
    ev.preventDefault();
    const fd = new FormData(ev.target), q = new URLSearchParams();
    for (const k of ["from","span","type","aud","p","zip"]) if (fd.get(k)) q.set(k, String(fd.get(k)).trim());
    if (fd.get("zip")) q.set("mi", fd.get("mi"));
    location.href = catHref(c) + (q.toString() ? "?" + q : "");
  });
}

const pageUrl = (u, pg) => pg && !u.includes("#") ? `${u}#page=${pg}` : u;
function bulletinRef(s){
  if (!s) return "the bulletin";
  const [p,u,pg] = s;
  const label = pg ? `the bulletin, page ${pg}` : "the bulletin";
  return u ? `<a href="${esc(pageUrl(u,pg))}" target="_blank" rel="noopener">${label}</a>` : label;
}
function detail(id){
  const e = byId[id];
  if (!e){ main.innerHTML = `<p class="center">That event is no longer listed. <a href="/">Back to the home page</a></p>`; return; }
  const vp = e.cat !== "Catholic events";
  const c = CATS.find(x => x.n === e.cat) || CATS[3];
  const q = new URLSearchParams(location.search);
  const d = q.get("d") || e.dates[0] || e.ds;
  let when = e.de && e.ds ? `${shortDay(e.ds)} through ${shortDay(e.de)}` : longDay(d) + ", " + pd(d).getFullYear();
  const time = e.st ? tm(e.st) + (e.et ? " to " + tm(e.et) : "") :
               e.dn ? "" : `Time not printed, check the ${vp ? "listing" : "bulletin"}`;
  const others = e.rec || (vp && e.dates.length > 1) ? e.dates.filter(x => x !== d) : [];
  const aud = (AUD.find(a => a[0]===e.au)||["",e.au])[1];
  // The text names the event and date, then links to this event's page.
  const link = `${location.origin}/event/${e.id}/?d=${d}`;
  const ask = sms(`Hi Mick, want to go to ${e.t} on ${longDay(d)}? ${link}`);
  const sources = vp
    ? `<dt>Listed on</dt><dd>${e.src.map(([p,u],i)=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(p)}${e.src.length>1?` (listing ${i+1})`:""}</a>`).join("<br>")}</dd>`
    : `<dt>From the bulletin of</dt><dd>${e.src.map(([p,u,pg])=>u?`<a href="${esc(pageUrl(u,pg))}" target="_blank" rel="noopener">${esc(p)}</a>${pg?`, page ${pg}`:""}`:esc(p)).join("<br>")}</dd>`;
  main.innerHTML = catNav(c.s) + `
    <h2 style="font-size:28px;font-weight:normal;margin:0 0 8px">${esc(e.t)}</h2>
    ${e.d ? `<p>${esc(e.d)}</p>` : ""}
    <dl>
      <dt>When</dt><dd>${esc(when)}${time?`<br>${esc(time)}`:""}${e.dn?`<br><span class="note">${esc(e.dn)}</span>`:""}${e.rec?`<br><span class="note">Repeats: ${esc(e.rec)}</span>`:""}</dd>
      ${others.length?`<dt>Also on</dt><dd>${others.map(x=>`<a href="/event/${e.id}/?d=${x}">${esc(longDay(x))}</a>`).join("<br>")}</dd>`:""}
      <dt>Where</dt><dd>${esc(e.v)}<br>${esc(e.a)}${(e.lt||[]).length?`<br><span class="where">Listed as: ${e.lt.map(x => "“" + esc(x) + "”").join("; ")}</span>`:""}</dd>
      ${e.adm?`<dt>Admission</dt><dd>${esc(e.adm)}</dd>`:""}
      ${!vp && (e.rq||e.ct)?`<dt>${e.rq?"Sign up":"Contact"}</dt><dd>${e.rq?"Sign-up required. ":""}Contact details are in ${bulletinRef(e.src[0])}.</dd>`:""}
      ${!vp ? `<dt>Kind</dt><dd>${esc(e.ty)}, for ${esc(aud.toLowerCase())}</dd>` : ""}
      ${sources}
    </dl>
    <p class="center" style="margin:22px 0 8px">Don't want to go alone?</p>
    <p class="center" style="margin:0"><a class="btn" href="${ask}">Let me join you</a></p>
    <p class="center muted small" style="margin:12px 0 22px">Or just text me at ${esc(PHONE_SHOWN)}.</p>
    <p class="center"><a href="${catHref(c)}">Back to ${esc(lower(c))}</a></p>`;
}

const WEEKDAYS = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
function schedules(){
  const q = new URLSearchParams(location.search);
  const f = {p:q.get("p")||"", k:q.get("k")||"", day:q.get("day")||"", zip:(q.get("zip")||"").trim(), mi:q.get("mi")||"10"};
  const home = f.zip ? ZIPS[f.zip] : null;
  const badZip = f.zip && !home;
  const opt = (v,l,cur) => `<option value="${esc(v)}"${v===cur?" selected":""}>${esc(l)}</option>`;
  const dayOrder = [6,0,1,2,3,4,5];
  let html = catNav("catholic") + `
    <p class="spaced">SCHEDULES</p>
    <p>The regular Mass, confession, and adoration times at each parish, read from the parish websites once a month. Holy days, holidays, and other special times are on the <a href="/events/catholic/">Catholic events list</a>.</p>
    <form class="filters" id="sf">
      <label>Parish <select name="p">${opt("","every parish",f.p)}${SCHED.map(P=>opt(P.p,P.p,f.p)).join("")}</select></label><br>
      <label>Show <select name="k">${opt("","Mass, confession & adoration",f.k)}${KINDS.map(k=>opt(k,k,f.k)).join("")}</select></label>
      <label>On <select name="day">${opt("","any day",f.day)}${dayOrder.map(i=>opt(String(i),WEEKDAYS[i],f.day)).join("")}</select></label><br>
      <label>Near zip <input name="zip" size="5" maxlength="5" inputmode="numeric" value="${esc(f.zip)}" placeholder="15222"></label>
      <label>within <select name="mi">${["5","10","25","50"].map(m=>opt(m,m+" miles",f.mi)).join("")}</select></label>
      <button type="submit">Go</button>
      ${badZip?`<div class="note">I don’t have zip code ${esc(f.zip)}. Try a nearby zip in western Pennsylvania.</div>`:""}
    </form>`;
  const groups = [];
  for (const P of SCHED){
    if (f.p && P.p !== f.p) continue;
    const rows = P.rows.filter(r => (!f.k || r.k===f.k) && (f.day==="" || r.dd.includes(+f.day))
      && (!home || (r.ll && miles(home, r.ll) <= +f.mi)));
    if (!rows.length) continue;
    const near = home ? Math.min(...rows.map(r => miles(home, r.ll))) : 0;
    groups.push({P, rows, near});
  }
  if (home) groups.sort((a,b) => a.near - b.near);
  html += `<p class="count">${groups.length} parish${groups.length===1?"":"es"}</p>`;
  for (const {P, rows} of groups){
    html += `<h2 class="day">${esc(P.p)}</h2><p class="note" style="margin:4px 0">`;
    html += P.w ? `<a href="${esc(P.w)}" target="_blank" rel="noopener">Parish website</a>. ` : "";
    html += P.r ? `Read from the parish website ${esc(shortDay(P.r))}.` : "";
    if (P.f) html += ` The website couldn’t be read on ${esc(shortDay(P.f))}, so these are the times from ${esc(shortDay(P.r))}.`;
    html += `</p>`;
    for (const k of KINDS){
      const kr = rows.filter(r => r.k===k);
      if (!kr.length) continue;
      html += `<p class="kind">${k}</p><table class="sch">`;
      for (const r of kr) html += `<tr><td class="sd">${esc(r.dl)}</td><td class="st">${esc(r.tm)}</td><td>${esc(r.v)}${r.tw?", "+esc(r.tw):""}${home&&r.ll?`, ${miles(home,r.ll).toFixed(1)} mi`:""}${r.n?`<br><span class="where">${esc(r.n)}</span>`:""}</td></tr>`;
      html += `</table>`;
    }
  }
  if (!groups.length) html += `<p class="center">Nothing matches. Try any day, or a wider distance.</p>`;
  main.innerHTML = html;
  document.getElementById("sf").addEventListener("submit", ev => {
    ev.preventDefault();
    const fd = new FormData(ev.target), q = new URLSearchParams();
    for (const k of ["p","k","day","zip"]) if (fd.get(k)) q.set(k, String(fd.get(k)).trim());
    if (fd.get("zip")) q.set("mi", fd.get("mi"));
    location.href = "/schedules/" + (q.toString() ? "?" + q : "");
  });
}

function support(){
  main.innerHTML = `<p class="spaced">SUPPORT THIS SITE</p>
    <p>Let Me Join You is an early stage project. Eventually I might have a donate button on this page, or some other way(s) for you to financially support it.</p>
    <p>But for now you can support the site by sharing it with people who might benefit from it or be able to give it a broader audience here in Pittsburgh.</p>
    <p>If you'd like to volunteer your time to hang out with lonely folks, send me an email at <a href="mailto:hi@letmejoinyou.com">hi@letmejoinyou.com</a> or text me at ${esc(PHONE_SHOWN)}.</p>
    <p>Thanks,<br>Mick</p>
    <p class="center"><a href="/">Back home</a></p>`;
}

function privacy(){
  main.innerHTML = `<p class="spaced">PRIVACY</p>
    <p>If you sign up for the email, I keep your address on a private list so I can send you things (weekly events and general LMJY updates). To get off the list, reply to any email or write to <a href="mailto:hi@letmejoinyou.com">hi@letmejoinyou.com</a>. If you text me, your number stays in my messages. I don't share or sell any emails or phone numbers.</p>
    <p class="center"><a href="/">Back home</a></p>`;
}

// The sign-up box sends the address to the sign-up sheet (a Google Apps
// Script web app that only adds a row) and says thanks in place.
document.addEventListener("submit", async ev => {
  if (ev.target.id !== "signup") return;
  ev.preventDefault();
  const f = ev.target, msg = document.getElementById("signupMsg");
  const body = new URLSearchParams({email: f.email.value.trim(), website: f.website.value});
  const btn = f.querySelector("button");
  btn.disabled = true;
  btn.textContent = "Signing up…";
  try {
    await fetch(SITE.newsletter, {method: "POST", mode: "no-cors", body});
    f.hidden = true;
    msg.textContent = "Thanks, you're on the list.";
  } catch (e) {
    btn.disabled = false;
    btn.textContent = "Sign up";
    msg.textContent = "That didn't go through. Try again, or email hi@letmejoinyou.com.";
  }
});

// Old links (texts already sent, bookmarks) used letmejoinyou.com/#/...;
// each goes to the same page at its real address.
function oldLink(h){
  const [path, qs = ""] = h.slice(1).split("?");
  const q = new URLSearchParams(qs);
  const tail = x => x.toString() ? "?" + x : "";
  if (path.startsWith("/events")) { const c = catBySlug[q.get("cat")] ? q.get("cat") : "catholic"; q.delete("cat"); return `/events/${c}/` + tail(q); }
  if (path.startsWith("/catholic")) return "/events/catholic/";
  if (path.startsWith("/event/")) return `/event/${path.slice(7)}/` + tail(q);
  if (path.startsWith("/schedules")) return "/schedules/" + tail(q);
  if (path.startsWith("/privacy")) return "/privacy/";
  if (path.startsWith("/support")) return "/support/";
  return "/";
}
function notFound(){
  main.innerHTML = `<p class="center">That page isn't here. <a href="/">Back to the home page</a></p>`;
}
function route(){
  if (location.hash.startsWith("#/")) { location.replace(oldLink(location.hash)); return; }
  const p = location.pathname;
  let m;
  if (p === "/" || p === "/index.html") home();
  else if ((m = p.match(/^\/events\/([a-z]+)\/?$/)) && catBySlug[m[1]]) list(m[1]);
  else if ((m = p.match(/^\/event\/([0-9a-z-]+)\/?$/))) detail(m[1]);
  else if (/^\/schedules\/?$/.test(p)) schedules();
  else if (/^\/support\/?$/.test(p)) support();
  else if (/^\/privacy\/?$/.test(p)) privacy();
  else notFound();
}
route();
